#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
적립식 평단 계산기 (실시간 시세 버전)

실행:  python dca_calculator.py
       (맥/리눅스는 python3 dca_calculator.py)
그러면 브라우저에 http://127.0.0.1:8765 가 열립니다.
끄려면 이 창에서 Ctrl+C.

- 파이썬 3.8 이상, 추가 설치 없음 (표준 라이브러리만 사용)
- 시세는 야후 파이낸스 공개 차트 데이터를 내 컴퓨터에서 직접 받아옵니다.
- 서버는 내 컴퓨터(127.0.0.1)에서만 열리고 외부에서는 접속할 수 없습니다.
"""
import base64, gzip, json, os, socket, ssl, sys, threading, time, webbrowser, zlib
import http.cookiejar
import urllib.error, urllib.parse, urllib.request
from datetime import datetime, timedelta, timezone
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

PORT = int(os.environ.get("DCA_PORT", "8765"))
MOCK = os.environ.get("DCA_MOCK") == "1"   # 개발용: 가짜 시세
CACHE_TTL = 600
UA = ("Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 "
      "(KHTML, like Gecko) Chrome/124.0 Safari/537.36")

PAGE_B64 = ""
PAGE = zlib.decompress(base64.b64decode(PAGE_B64))

# ---------- 네트워크 ----------
def _ssl_context():
    try:
        import certifi  # 있으면 사용 (맥 python.org 설치본의 인증서 문제 예방)
        return ssl.create_default_context(cafile=certifi.where())
    except Exception:
        return ssl.create_default_context()

_jar = http.cookiejar.CookieJar()
_opener = urllib.request.build_opener(
    urllib.request.HTTPCookieProcessor(_jar),
    urllib.request.HTTPSHandler(context=_ssl_context()))
_crumb = None
_lock = threading.Lock()
_cache = {}

class FetchError(Exception):
    pass

def _get(url):
    req = urllib.request.Request(url, headers={
        "User-Agent": UA, "Accept": "application/json,text/plain,*/*",
        "Accept-Language": "en-US,en;q=0.9", "Accept-Encoding": "gzip"})
    with _opener.open(req, timeout=20) as r:
        data = r.read()
        if r.headers.get("Content-Encoding") == "gzip":
            data = gzip.decompress(data)
        return data

def _refresh_crumb():
    global _crumb
    try:
        _get("https://fc.yahoo.com")
    except Exception:
        pass  # 404여도 쿠키는 받음
    try:
        _crumb = _get("https://query1.finance.yahoo.com/v1/test/getcrumb").decode().strip() or None
    except Exception:
        _crumb = None

def yahoo(path_and_query):
    """query1 → query2 순서로 시도, 인증 오류면 crumb 받아서 한 번 더."""
    last_err = None
    for attempt in range(2):
        for host in ("query1", "query2"):
            url = "https://%s.finance.yahoo.com%s" % (host, path_and_query)
            if _crumb:
                url += ("&" if "?" in url else "?") + "crumb=" + urllib.parse.quote(_crumb)
            try:
                return json.loads(_get(url).decode("utf-8"))
            except urllib.error.HTTPError as e:
                body = ""
                try:
                    body = e.read().decode("utf-8", "replace")
                    j = json.loads(body)
                    if j.get("chart", {}).get("error"):
                        return j  # 야후가 준 오류 메시지 그대로 전달
                except Exception:
                    pass
                last_err = "야후 응답 %s" % e.code
                if e.code in (401, 403, 429) and attempt == 0:
                    break
            except ssl.SSLError as e:
                raise FetchError("SSL 인증서 확인에 실패했습니다. 맥이라면 '응용 프로그램 > Python 3.x > "
                                 "Install Certificates.command'를 한 번 실행하거나, 'pip install certifi' 후 다시 실행해 주세요. (%s)" % e)
            except urllib.error.URLError as e:
                if isinstance(e.reason, ssl.SSLError):
                    raise FetchError("SSL 인증서 확인에 실패했습니다. 맥이라면 'Install Certificates.command'를 실행하거나 "
                                     "'pip install certifi' 후 다시 실행해 주세요.")
                last_err = "인터넷 연결을 확인해 주세요 (%s)" % e.reason
            except Exception as e:
                last_err = str(e)
        if attempt == 0:
            with _lock:
                _refresh_crumb()
    raise FetchError(last_err or "시세를 받아오지 못했습니다.")

# ---------- API ----------
def chart(symbol):
    key = ("chart", symbol)
    hit = _cache.get(key)
    if hit and time.time() - hit[0] < CACHE_TTL:
        return hit[1]
    if MOCK:
        out = _mock_chart(symbol)
    else:
        now = int(time.time()) + 86400
        q = "/v8/finance/chart/%s?period1=0&period2=%d&interval=1d&events=div%%2Csplits&includeAdjustedClose=true" % (
            urllib.parse.quote(symbol, safe=""), now)
        j = yahoo(q)
        c = j.get("chart") or {}
        if c.get("error"):
            desc = c["error"].get("description") or c["error"].get("code") or ""
            raise FetchError("'%s' 종목을 찾지 못했습니다. 코드를 확인해 주세요. (%s)" % (symbol, desc))
        res = (c.get("result") or [None])[0]
        if not res or not res.get("timestamp"):
            raise FetchError("'%s' 종목의 시세 데이터가 없습니다." % symbol)
        meta = res.get("meta", {})
        off = int(meta.get("gmtoffset") or 0)
        ts = res["timestamp"]
        quote = (res.get("indicators", {}).get("quote") or [{}])[0]
        close = quote.get("close") or []
        opn, high, low, vol = (quote.get(k) or [] for k in ("open", "high", "low", "volume"))
        adj = ((res.get("indicators", {}).get("adjclose") or [{}])[0] or {}).get("adjclose") or [None] * len(ts)
        by_date = {}
        epoch = datetime(1970, 1, 1, tzinfo=timezone.utc)
        pick = lambda arr, i: arr[i] if i < len(arr) and arr[i] is not None and arr[i] > 0 else None
        for i, t in enumerate(ts):
            c_ = close[i] if i < len(close) else None
            if c_ is None or c_ <= 0:
                continue
            a_ = adj[i] if i < len(adj) and adj[i] else c_
            o_ = pick(opn, i) or c_
            h_ = max(pick(high, i) or c_, o_, c_)
            l_ = min(pick(low, i) or c_, o_, c_)
            v_ = vol[i] if i < len(vol) and vol[i] else 0
            d = (epoch + timedelta(seconds=t + off)).strftime("%Y-%m-%d")
            # [날짜, 종가, 수정종가, 시가, 고가, 저가, 거래량]
            by_date[d] = [d, round(c_, 4), round(a_, 4), round(o_, 4), round(h_, 4), round(l_, 4), int(v_)]
        data = [by_date[k] for k in sorted(by_date)]
        if len(data) < 2:
            raise FetchError("'%s' 종목의 시세 데이터가 너무 적습니다." % symbol)
        out = {
            "symbol": symbol,
            "name": meta.get("longName") or meta.get("shortName") or symbol,
            "currency": (meta.get("currency") or "USD").upper(),
            "exchange": meta.get("fullExchangeName") or meta.get("exchangeName") or "",
            "data": data,
        }
    _cache[key] = (time.time(), out)
    return out

def search(q):
    if MOCK:
        return {"quotes": [{"symbol": "AAPL", "name": "Apple Inc.", "type": "EQUITY", "exchange": "NASDAQ"}]}
    j = yahoo("/v1/finance/search?q=%s&quotesCount=10&newsCount=0&listsCount=0&lang=en-US" % urllib.parse.quote(q))
    quotes = []
    for x in j.get("quotes", []):
        if not x.get("symbol"):
            continue
        quotes.append({"symbol": x["symbol"], "name": x.get("longname") or x.get("shortname") or x["symbol"],
                       "type": x.get("quoteType", ""), "exchange": x.get("exchDisp") or x.get("exchange", "")})
    return {"quotes": quotes}

def _mock_chart(symbol):
    import math, random
    rnd = random.Random(symbol)
    cur = "KRW" if symbol.endswith((".KS", ".KQ")) or symbol in ("^KS11", "^KQ11") or symbol.endswith("KRW=X") or symbol == "KRW=X" else "USD"
    p = 1200.0 if symbol == "KRW=X" else (2000.0 if cur == "KRW" else 100.0)
    d = datetime(2005, 1, 3); end = datetime(2026, 10, 23); data = []
    while d <= end:
        if d.weekday() < 5:
            o = p * math.exp(0.003 * rnd.gauss(0, 1))
            p *= math.exp(0.0002 + 0.012 * rnd.gauss(0, 1))
            h = max(o, p) * (1 + abs(0.006 * rnd.gauss(0, 1)))
            l = min(o, p) * (1 - abs(0.006 * rnd.gauss(0, 1)))
            data.append([d.strftime("%Y-%m-%d"), round(p, 4), round(p * 0.98, 4), round(o, 4), round(h, 4), round(l, 4),
                         int(400000 * (1 + abs(rnd.gauss(0, 0.5))))])
        d += timedelta(days=1)
    return {"symbol": symbol, "name": "MOCK " + symbol, "currency": cur, "exchange": "MOCK", "data": data}

# ---------- HTTP ----------
class Handler(BaseHTTPRequestHandler):
    def log_message(self, fmt, *args):
        pass

    def _send(self, code, body, ctype):
        self.send_response(code)
        self.send_header("Content-Type", ctype)
        self.send_header("Cache-Control", "no-store")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def _json(self, code, obj):
        self._send(code, json.dumps(obj, ensure_ascii=False, separators=(",", ":")).encode("utf-8"),
                   "application/json; charset=utf-8")

    def do_GET(self):
        u = urllib.parse.urlparse(self.path)
        qs = urllib.parse.parse_qs(u.query)
        try:
            if u.path in ("/", "/index.html"):
                self._send(200, PAGE, "text/html; charset=utf-8")
            elif u.path == "/api/chart":
                sym = (qs.get("symbol") or [""])[0].strip()
                if not sym or len(sym) > 32:
                    return self._json(400, {"error": "종목 코드를 입력해 주세요."})
                self._json(200, chart(sym))
            elif u.path == "/api/search":
                q = (qs.get("q") or [""])[0].strip()
                if not q:
                    return self._json(200, {"quotes": []})
                self._json(200, search(q[:64]))
            else:
                self._json(404, {"error": "없는 주소입니다."})
        except FetchError as e:
            self._json(502, {"error": str(e)})
        except Exception as e:
            self._json(500, {"error": "처리 중 오류: %s" % e})

def main():
    port = PORT
    for _ in range(20):
        try:
            srv = ThreadingHTTPServer(("127.0.0.1", port), Handler)
            break
        except OSError:
            port += 1
    else:
        print("사용할 수 있는 포트를 찾지 못했습니다.")
        sys.exit(1)
    url = "http://127.0.0.1:%d" % port
    try:
        print("적립식 평단 계산기 실행 중: %s" % url)
        print("끄려면 Ctrl+C")
    except Exception:
        print("DCA calculator running: %s  (Ctrl+C to stop)" % url)
    if os.environ.get("DCA_NO_BROWSER") != "1":
        threading.Timer(0.8, lambda: webbrowser.open(url)).start()
    try:
        srv.serve_forever()
    except KeyboardInterrupt:
        pass

if __name__ == "__main__":
    main()
